import {money,esc,status,latest,safeLink,validatePing,validateState,alertFor,milesComparison,freshState,demoState} from './core.js';
import {cloudConfig,configureCloud,signedIn,signIn,signOut,readCloud,writeCloud,cloudRevision} from './cloud-v2.js';
const STORE='aeroping-v1', main=document.querySelector('#main'),modal=document.querySelector('#modal');
let state,filter='all',view='',revision=null,cloudBusy=false,cloudDirty=false,cloudConflict=false,cloudTimer,installPrompt,toastTimer;
try{const saved=localStorage.getItem(STORE);state=saved?validateState(JSON.parse(saved)):freshState();}catch{state=freshState();queueMicrotask(()=>toast('Não foi possível ler os dados. Você pode restaurar um backup nos ajustes.'));}
let accessRenderer=()=>'<div class="loading">Conectando ao AeroPing…</div>',settingsRenderer=null;
const titleMap={radar:'Meu radar',viagens:'Nossas viagens',milhas:'Dinheiro ou milhas',alertas:'Central de pings',ajustes:'Ajustes'};
const statusName={hit:'Preço-alvo atingido',warm:'Na zona de calor',watch:'De olho no preço',paused:'Radar pausado',empty:'Aguardando cotação'};
const day=s=>new Date(s+'T12:00:00').toLocaleDateString('pt-BR',{day:'2-digit',month:'short'}).replace('.','');
const stamp=s=>new Date(s).toLocaleDateString('pt-BR',{day:'2-digit',month:'short'});
const uid=()=>crypto.randomUUID();
const pingById=id=>state.pings.find(p=>p.id===id);
const pageHeader=(eyebrow,title,description,button='')=>`<div class="page-heading"><div><div class="eyebrow"><span class="live-dot"></span>${eyebrow}</div><h1>${title}</h1><p>${description}</p></div>${button}</div>`;
function toast(message){clearTimeout(toastTimer);const el=document.querySelector('#toast');el.textContent=message;el.classList.add('visible');toastTimer=setTimeout(()=>el.classList.remove('visible'),5000);}
function save(){try{localStorage.setItem(STORE,JSON.stringify(state));}catch{toast('Armazenamento cheio ou indisponível. Exporte um backup.');}if(signedIn()&&revision!==null&&!cloudConflict){cloudDirty=true;clearTimeout(cloudTimer);cloudTimer=setTimeout(pushCloud,1200);}updateShell();}
function event(type,title,body,demo=false){state.events.unshift({id:uid(),type,title,body,at:new Date().toISOString(),demo});state.events=state.events.slice(0,500);}
function updateShell(){document.querySelector('#nav-count').textContent=state.pings.filter(p=>!p.paused).length;document.querySelectorAll('#alert-dot,#top-dot').forEach(e=>e.hidden=!state.events.some(e=>!e.read));document.querySelector('#storage-label').textContent=cloudConflict?'Conflito: confira os ajustes':signedIn()?(cloudDirty?'Alterações para sincronizar':revision===null?'Nuvem aguardando conexão':'Sincronizado com o casal'):'Acesso privado do casal';}
function chart(p,large=false){const values=p.quotes.map(q=>q.price);if(!values.length)return `<svg class="${large?'large-chart':'sparkline'}" viewBox="0 0 300 60" role="img" aria-label="Sem histórico de preços"><path d="M0 45H300" stroke="#334252" stroke-dasharray="4 5"/><text x="150" y="30" fill="#7a8c9c" font-size="9" text-anchor="middle">Registre a primeira cotação</text></svg>`;
 const w=large?600:300,h=large?190:65,pad=large?20:7;const min=Math.min(...values,p.target)*.94,max=Math.max(...values,p.target)*1.04,range=max-min||1;const y=n=>h-pad-(n-min)/range*(h-2*pad);const coords=values.map((v,i)=>[values.length===1?w/2:i/(values.length-1)*w,y(v)]);const points=coords.map(x=>x.join(',')).join(' '),last=coords.at(-1),color=status(p)==='hit'?'#b6f58a':status(p)==='warm'?'#f4c475':'#8ca9bc';const gid='g'+p.id.replace(/[^\w]/g,'')+(large?'l':'s');
 return `<svg class="${large?'large-chart':'sparkline'}" viewBox="0 0 ${w} ${h}" preserveAspectRatio="none" role="img" aria-label="Histórico de ${esc(p.city)}, cotação atual ${esc(money(values.at(-1)))}; linha tracejada: meta de ${esc(money(p.target))}"><defs><linearGradient id="${gid}" x1="0" y1="0" x2="0" y2="1"><stop stop-color="${color}" stop-opacity=".16"/><stop offset="1" stop-color="${color}" stop-opacity="0"/></linearGradient></defs><path d="M0 ${y(p.target)}H${w}" stroke="#a2bb8f" opacity=".35" stroke-dasharray="4 5"/><path d="M${coords[0].join(',')} L${points} L${last[0]},${h} L${coords[0][0]},${h}Z" fill="url(#${gid})"/><polyline points="${points}" fill="none" stroke="${color}" stroke-width="${large?2:1.6}" stroke-linejoin="round" vector-effect="non-scaling-stroke"/><circle cx="${last[0]}" cy="${last[1]}" r="${large?3.5:2.5}" fill="${color}"/></svg>`;
}
function card(p){const st=status(p),n=latest(p),difference=n==null?null:n-p.target;const pct=n==null?0:Math.min(100,p.target/n*100);return `<article class="trip-card ${p.paused?'paused':''}"><div class="card-photo ${['lisbon','paris','tokyo'].includes(p.photo)?p.photo:'other'}"><span class="photo-tag ${st==='warm'?'warm':['hit'].includes(st)?'':'neutral'}">${st==='hit'?'↘':st==='warm'?'◉':'◌'} ${statusName[st]}</span><div class="photo-actions"><button data-action="edit" data-id="${esc(p.id)}" aria-label="Editar radar de ${esc(p.city)}">⋯</button></div><div class="destination"><div><h3>${esc(p.city)}</h3><p>${esc(p.country||'Nossa próxima viagem')}${p.demo?' · demonstração':''}</p></div><span>↗</span></div></div><div class="card-body"><div class="route"><strong>${esc(p.origin)}</strong><span>── ✈ ──</span><strong>${esc(p.destination)}</strong><span style="flex:0;font-size:8px;letter-spacing:0;margin-left:auto">IDA E VOLTA</span></div><div class="trip-info">▦ ${day(p.depart)} – ${day(p.return)} <span>·</span> 2 adultos <span>·</span> ${p.stops==='direct'?'Direto':p.stops==='one'?'Até 1 parada':'Flexível'}</div><div class="price-row"><div><label>Última cotação / pessoa</label><strong class="price ${st==='hit'?'green':''}">${n==null?'—':`<small>R$</small> ${new Intl.NumberFormat('pt-BR').format(n)}`}</strong></div><div class="target"><label>Nosso alvo</label><strong>${money(p.target)}</strong></div></div>${chart(p)}<div class="chart-labels"><span>${p.quotes.length?stamp(p.quotes[0].at):'Sem cotações'}</span><span>┄ preço-alvo</span><span>${p.quotes.length?stamp(p.quotes.at(-1).at):''}</span></div><div class="target-status"><span>${difference==null?'O próximo passo é registrar um preço':difference<=0?'✧ '+money(-difference)+' abaixo da meta':'Faltam '+money(difference)+' para a meta'}</span><span>${difference==null?'—':Math.round(pct)+'%'}</span></div><div class="progress"><span style="width:${pct}%;${st==='warm'?'background:var(--gold)':st==='watch'?'background:#7d9cad':''}"></span></div><div class="card-footer"><span>${p.demo?'◌ Histórico ilustrativo':p.quotes.length?'◷ Registrado em '+stamp(p.quotes.at(-1).at):'◷ Sem registro de preço'}</span><button data-action="detail" data-id="${esc(p.id)}">Ver radar ↗</button></div></div></article>`;}
function radarSvg(){return `<svg viewBox="0 0 360 360" fill="none" aria-hidden="true"><defs><linearGradient id="sweep"><stop stop-color="#b6f58a" stop-opacity=".2"/><stop offset="1" stop-color="#b6f58a" stop-opacity="0"/></linearGradient></defs><circle cx="180" cy="180" r="143" stroke="#9ec193" stroke-opacity=".14"/><circle cx="180" cy="180" r="108" stroke="#9ec193" stroke-opacity=".17"/><circle cx="180" cy="180" r="73" stroke="#9ec193" stroke-opacity=".2"/><circle cx="180" cy="180" r="38" stroke="#9ec193" stroke-opacity=".25"/><path d="M180 20V340M20 180H340M67 67L293 293M67 293L293 67" stroke="#9ec193" stroke-opacity=".08"/><g class="radar-sweep"><path d="M180 180L180 37A143 143 0 0 1 323 180Z" fill="url(#sweep)"/><path d="M180 180L323 180" stroke="#b6f58a" stroke-opacity=".4"/></g><circle cx="249" cy="133" r="5" fill="#b6f58a"/><circle cx="249" cy="133" r="12" stroke="#b6f58a" stroke-opacity=".3"/><circle cx="117" cy="211" r="3" fill="#b6f58a"/><circle cx="198" cy="262" r="3" fill="#b6f58a" fill-opacity=".6"/><circle cx="180" cy="180" r="4" fill="#b6f58a"/><text x="266" y="130" fill="#b6f58a" font-size="9" font-family="monospace">LIS</text><text x="96" y="231" fill="#95b28d" font-size="9" font-family="monospace">GRU</text><text x="209" y="279" fill="#95b28d" font-size="9" font-family="monospace">HND</text></svg>`;}
function activity(e){return `<div class="activity"><div class="activity-icon ${e.type==='warm'?'warm':''}">${e.type==='hit'?'↘':e.type==='warm'?'◉':e.type==='vote'?'♡':'↗'}</div><div><strong>${esc(e.title)} ${e.demo?'<span class="demo-chip">EXEMPLO</span>':''}</strong><p>${esc(e.body)}</p></div><time datetime="${esc(e.at)}">${stamp(e.at)}</time></div>`;}
function empty(message='Crie o radar da próxima viagem.',description='Escolha um destino, defina quanto vocês querem pagar e comece a acompanhar as cotações.'){return `<div class="empty"><div class="empty-icon">◉</div><h2>${message}</h2><p>${description}</p><button class="btn primary" data-action="new">＋ Criar nosso primeiro ping</button></div>`;}
function renderRadar(){const pings=state.pings,active=pings.filter(p=>!p.paused),hits=active.filter(p=>status(p)==='hit'),warm=active.filter(p=>status(p)==='warm'),saving=hits.reduce((a,p)=>a+(p.target-latest(p))*2,0);const selected=filter==='hit'?pings.filter(p=>status(p)==='hit'):filter==='warm'?pings.filter(p=>status(p)==='warm'):pings;return pageHeader('NOSSO PRÓXIMO DESTINO','Bons planos começam aqui.','O mundo é grande. O preço da passagem não precisa ser.','<button class="btn primary" data-action="new"><span>＋</span> Novo ping</button>')+`<section class="hero"><div class="hero-content"><div class="pill"><span class="live-dot"></span> DOIS VIAJANTES. MUITAS POSSIBILIDADES.</div><h2>Vocês escolhem o destino.<br>A gente cuida <em>da meta.</em></h2><p>Reúna os planos, acompanhe os preços e reconheça a hora certa de fazer as malas. Tudo no mesmo lugar.</p><div class="hero-bottom">↗ ${active.length} ${active.length===1?'destino no radar':'destinos no radar'} <span style="margin:0 6px;color:#476252">/</span> Um próximo capítulo esperando por vocês</div></div><div class="hero-radar">${radarSvg()}</div><div class="hero-coordinate">23°33′ S &nbsp; 46°38′ W &nbsp; · &nbsp; GRU</div></section><section class="stats" aria-label="Resumo dos radares"><div class="stat"><div class="stat-label">Radares ativos <span>◉</span></div><div class="stat-value">${String(active.length).padStart(2,'0')}</div><small>${pings.some(p=>p.demo)?'Inclui radares de demonstração':'Destinos que estão nos nossos planos'}</small></div><div class="stat"><div class="stat-label">No preço-alvo <span>↘</span></div><div class="stat-value green">${String(hits.length).padStart(2,'0')}</div><small class="green">${hits.length?'Cotações dentro da nossa meta':'Esperando a próxima oportunidade'}</small></div><div class="stat"><div class="stat-label">Quase lá <span>◌</span></div><div class="stat-value">${String(warm.length).padStart(2,'0')}</div><small>Dentro da margem de tolerância</small></div><div class="stat"><div class="stat-label">Abaixo do orçamento <span>◇</span></div><div class="stat-value">${money(saving)}</div><small>${pings.some(p=>p.demo)?'Ilustração para o casal · não realizada':'Diferença para a meta do casal · não realizada'}</small></div></section><div class="section-heading"><div><h2>Nossos radares <span>${pings.length}</span></h2><p>Um olho no destino. Outro no preço.</p></div><div class="tabs" role="group" aria-label="Filtrar radares">${[['all','Todos'],['hit','No alvo'],['warm','Quase lá']].map(([id,label])=>`<button data-action="filter" data-filter="${id}" class="${filter===id?'active':''}" aria-pressed="${filter===id}">${label}</button>`).join('')}</div></div><section class="cards">${selected.length?selected.map(card).join(''):pings.length?'<div class="empty"><h2>Nenhum radar neste filtro.</h2><p>As próximas oportunidades aparecem aqui.</p><button class="btn" data-action="filter" data-filter="all">Ver todos</button></div>':empty()}</section><div class="demo-notice">ⓘ ${pings.some(p=>p.demo)?'Os destinos e preços de exemplo são ilustrativos. Nenhuma oferta real foi consultada. <button data-action="clear-demo">Remover exemplos</button>':'Cotações registradas por você. Consultas automáticas ainda não estão conectadas.'}</div><section class="bottom-grid"><div class="panel"><div class="panel-top"><h2>Últimos sinais do radar</h2><a href="#alertas">Ver todos ↗</a></div>${state.events.slice(0,2).map(activity).join('')||'<p class="muted" style="font-size:11px;line-height:1.8">Quando uma cotação registrada chegar perto da meta, o ping aparece aqui.</p>'}</div><div class="panel together"><span class="badge">♡ MELHOR COMPARTILHADO</span><div class="together-avatars"><span class="avatar">${esc(state.settings.nameA[0]||'E')}</span><span class="avatar">${esc(state.settings.nameB[0]||'M')}</span></div><h3>O destino é de vocês.<br>A decisão também.</h3><p>Organizem as ideias, comparem as oportunidades e marquem aquele “eu topo” para a próxima aventura.</p><a class="btn ghost" href="#viagens">Planejar a dois <span>↗</span></a></div></section>`;}
function renderTrips(){return pageHeader('NOSSA LISTA DE DESEJOS','Próxima parada: juntos.','Uma boa viagem começa quando os dois dizem “eu topo”.','<button class="btn primary" data-action="new">＋ Novo destino</button>')+`<div class="hint">${signedIn()?'As decisões são compartilhadas entre vocês.':'Neste modo, as decisões ficam neste navegador. Para usar nos dois celulares, conecte o Supabase nos ajustes.'} Cada botão registra a decisão indicada pelo nome.</div><section class="trip-plan">${state.pings.length?state.pings.map(p=>`<article class="panel"><div class="plan-header"><div><span class="badge">${esc(p.origin)} → ${esc(p.destination)} ${p.demo?'· EXEMPLO':''}</span><h3 style="margin-top:12px">${esc(p.city)} a dois</h3><p class="detail-route">${day(p.depart)} a ${day(p.return)} · ${latest(p)==null?'Sem cotação':money(latest(p)*2)+' para o casal'}</p></div><button class="btn ghost" data-action="detail" data-id="${esc(p.id)}">Ver radar ↗</button></div><div class="votes">${[['a',state.settings.nameA],['b',state.settings.nameB]].map(([who,name])=>`<button class="btn ${p.votes?.[who]==='yes'?'selected':''}" data-action="vote" data-id="${esc(p.id)}" data-who="${who}">${p.votes?.[who]==='yes'?'✓':'♡'} ${esc(name)}: ${p.votes?.[who]==='yes'?'eu topo!':'ainda pensando'}</button>`).join('')}</div>${p.votes?.a==='yes'&&p.votes?.b==='yes'?'<p class="green" style="font-size:11px;margin-top:16px">✧ Combinado! Os dois toparam. Hora de conferir a tarifa na companhia.</p>':''}</article>`).join(''):empty()}</section>`;}
function renderMiles(){return pageHeader('CADA PONTO CONTA','Dinheiro ou milhas?','Transforme as duas opções na mesma moeda e decida com clareza.')+`<div class="compare-layout"><section class="panel"><h2 style="margin-bottom:23px">Vamos fazer as contas</h2><form id="miles-form"><div class="form-grid"><div class="field full"><label for="cash">Passagem em dinheiro (R$)</label><input id="cash" name="cash" type="number" min="1" max="10000000" step=".01" value="3200" required><small>Por pessoa, mesmo trecho e mesmas condições.</small></div><div class="field"><label for="miles">Quantidade de milhas</label><input id="miles" name="miles" type="number" min="1" max="100000000" value="80000" required></div><div class="field"><label for="thousand">Valor do milheiro (R$)</label><input id="thousand" name="thousand" type="number" min="0" max="10000" step=".01" value="25" required></div><div class="field full"><label for="taxes">Taxas da emissão com milhas (R$)</label><input id="taxes" name="taxes" type="number" min="0" max="1000000" step=".01" value="350" required></div></div><div class="form-actions"><button class="btn primary" type="submit">Comparar opções ↗</button></div></form></section><section class="panel"><span class="badge">◇ UMA DECISÃO MAIS CLARA</span><h2 style="margin-top:20px;font-size:23px;line-height:1.5">Suas milhas também<br>têm valor.</h2><p class="muted" style="font-size:12px;line-height:1.9;margin-top:17px">Informe o custo de compra ou o valor que você atribui às suas milhas. Mesmo os pontos já acumulados têm um custo de oportunidade.</p><div id="miles-result" aria-live="polite"></div><p class="price-source">Os valores preenchidos são exemplos editáveis. O cálculo considera milhas × custo do milheiro + taxas. Compare bagagem, regras de alteração e o mesmo número de passageiros. Nenhum programa de fidelidade é consultado.</p></section></div>`;}
function renderAlerts(){return pageHeader('A HORA CERTA DE FAZER AS MALAS','Cada ping, uma possibilidade.','Os sinais dos seus radares e as decisões de vocês, em um só lugar.','<button class="btn ghost" data-action="read-alerts">Marcar como lidos</button>')+`<div class="hint">Alertas são calculados quando uma cotação é registrada. O app ainda não busca preços em segundo plano. Notificações do navegador, quando permitidas, funcionam com o app aberto.</div><div class="panel event-list">${state.events.length?state.events.map(activity).join(''):'<div class="empty"><div class="empty-icon">♧</div><h2>O próximo sinal aparece aqui.</h2><p>Crie um radar e registre cotações para acompanhar as mudanças de preço.</p></div>'}</div>`;}
function render(){view=location.hash.slice(1)||'radar';if(!titleMap[view])view='radar';document.querySelector('#page-name').textContent=titleMap[view];document.querySelectorAll('[data-nav]').forEach(e=>{e.classList.toggle('active',e.dataset.nav===view);if(e.dataset.nav===view)e.setAttribute('aria-current','page');else e.removeAttribute('aria-current');});main.innerHTML=!signedIn()?accessRenderer():revision===null?'<div class="loading">Conectando ao nosso espaço…</div>':view==='ajustes'&&settingsRenderer?settingsRenderer():({radar:renderRadar,viagens:renderTrips,milhas:renderMiles,alertas:renderAlerts,ajustes:()=>''}[view])();updateShell();}
function showDialog(title,description,body){document.querySelector('#modal-body').innerHTML=`<div class="modal-header"><div><h2>${title}</h2><p>${description}</p></div><button data-action="close" aria-label="Fechar">×</button></div>${body}<p class="modal-error" id="modal-error" role="alert"></p>`;if(!modal.open)modal.showModal();}
function showPingForm(id){const p=id?pingById(id):null;if(id&&!p)return;const today=new Date();today.setDate(today.getDate()+90);const dep=today.toISOString().slice(0,10);today.setDate(today.getDate()+10);const ret=today.toISOString().slice(0,10);showDialog(p?'Ajustar nosso radar':'Onde começa a próxima história?','Defina o destino e o preço que faz sentido para vocês.',`<form id="ping-form" data-id="${esc(p?.id||'')}"><div class="form-grid"><div class="field"><label for="city">Cidade de destino</label><input id="city" name="city" placeholder="Lisboa" value="${esc(p?.city||'')}" maxlength="80" required></div><div class="field"><label for="country">País (opcional)</label><input id="country" name="country" placeholder="Portugal" value="${esc(p?.country||'')}" maxlength="80"></div><div class="field"><label for="origin">Origem · código IATA</label><input id="origin" name="origin" placeholder="GRU" value="${esc(p?.origin||'GRU')}" maxlength="3" minlength="3" pattern="[A-Za-z]{3}" required style="text-transform:uppercase"></div><div class="field"><label for="destination">Destino · código IATA</label><input id="destination" name="destination" placeholder="LIS" value="${esc(p?.destination||'')}" maxlength="3" minlength="3" pattern="[A-Za-z]{3}" required style="text-transform:uppercase"></div><div class="field"><label for="depart">Ida</label><input id="depart" name="depart" type="date" value="${esc(p?.depart||dep)}" required></div><div class="field"><label for="return">Volta</label><input id="return" name="return" type="date" value="${esc(p?.return||ret)}" required></div><div class="field"><label for="target">Preço-alvo por pessoa (R$)</label><input id="target" name="target" type="number" min="1" max="10000000" step=".01" value="${p?.target||''}" placeholder="3500" required></div><div class="field"><label for="tolerance">Margem de tolerância (%)</label><input id="tolerance" name="tolerance" type="number" min="0" max="50" value="${p?.tolerance??10}" required></div><div class="field full"><label for="stops">Preferência de conexões</label><select id="stops" name="stops">${[['any','Qualquer número de paradas'],['direct','Somente voos diretos'],['one','No máximo 1 parada']].map(([v,t])=>`<option value="${v}" ${p?.stops===v?'selected':''}>${t}</option>`).join('')}</select><small>As preferências orientam seu registro manual; não filtram buscadores externos automaticamente.</small></div><label class="check-label" style="grid-column:1/-1"><input type="checkbox" name="baggage" ${p?.baggage?'checked':''}> Quero cotar com bagagem despachada</label></div><div class="hint">Meta por pessoa, ida e volta, para 2 adultos. Exemplo: meta de R$ 3.500 = orçamento de R$ 7.000 para o casal. As datas são exatas nesta versão.</div><div class="form-actions">${p?`<button class="btn danger" type="button" data-action="delete" data-id="${esc(p.id)}">Excluir radar</button>`:''}<button class="btn primary" type="submit">${p?'Salvar radar':'Criar nosso ping'} ↗</button></div></form>`);}
function detail(id){const p=pingById(id);if(!p)return;const n=latest(p);showDialog(`Nosso radar: ${esc(p.city)}`,`${esc(p.origin)} → ${esc(p.destination)} · ${day(p.depart)} a ${day(p.return)} · 2 adultos${p.demo?' · DEMONSTRAÇÃO':''}`,`<span class="badge">${statusName[status(p)]}</span><div class="details-prices"><div><div class="muted" style="font-size:10px">Última cotação / pessoa</div><div class="price ${status(p)==='hit'?'green':''}" style="margin-top:6px">${n==null?'—':money(n)}</div></div><div><div class="muted" style="font-size:10px">Nosso alvo / pessoa</div><div class="price" style="font-size:23px;margin-top:9px">${money(p.target)}</div></div></div>${chart(p,true)}<div class="chart-labels"><span>${p.quotes.length?stamp(p.quotes[0].at):''}</span><span>┄ preço-alvo</span><span>${p.quotes.length?stamp(p.quotes.at(-1).at):''}</span></div><div class="hint">${p.demo?'Histórico de demonstração. Remova o exemplo e crie um radar próprio para registrar ofertas reais.':p.quotes.length<3?'Registre mais cotações para enxergar a evolução. Ainda não há dados para avaliar uma tendência.':'O gráfico reflete apenas as cotações que você registrou. Não é uma previsão de preços.'} ${p.baggage?'Preferência: bagagem despachada.':''}</div><div class="toolbar">${p.demo?'':`<button class="btn primary" data-action="quote" data-id="${esc(p.id)}">＋ Registrar cotação</button>`}<button class="btn ghost" data-action="search" data-id="${esc(p.id)}">Pesquisar passagem ↗</button><button class="btn ghost" data-action="pause" data-id="${esc(p.id)}">${p.paused?'Retomar':'Pausar'}</button><button class="btn ghost" data-action="edit" data-id="${esc(p.id)}">Editar</button></div><div class="quote-list">${p.quotes.slice(-5).reverse().map(q=>`<div class="quote-row"><span>${stamp(q.at)} · ${esc(q.source)}</span><strong>${money(q.price)}</strong>${safeLink(q.url)?`<a href="${esc(safeLink(q.url))}" target="_blank" rel="noopener noreferrer">Fonte ↗</a>`:''}</div>`).join('')}</div>`);}
function quoteForm(id){const p=pingById(id);if(!p||p.demo)return;showDialog(`Uma nova cotação para ${esc(p.city)}`,'Registre o valor visto no site da companhia ou buscador.',`<form id="quote-form" data-id="${esc(p.id)}"><div class="form-grid"><div class="field full"><label for="quote-price">Valor final por pessoa · ida e volta (R$)</label><input id="quote-price" name="price" type="number" min="1" max="10000000" step=".01" required autofocus><small>Inclua as taxas e a bagagem que você deseja. Para o casal, dividimos o total por duas pessoas.</small></div><div class="field full"><label for="quote-source">Onde você encontrou?</label><input id="quote-source" name="source" placeholder="LATAM, Google Voos…" maxlength="200" required></div><div class="field full"><label for="quote-url">Link da oferta (opcional, HTTPS)</label><input id="quote-url" name="url" type="url" placeholder="https://…"></div><label class="check-label" style="grid-column:1/-1"><input name="checked" type="checkbox" required> Conferi as datas, os 2 adultos e as preferências do radar.</label></div><div class="form-actions"><button class="btn primary" type="submit">Registrar e avaliar meta ↗</button></div></form>`);}
function confirmDialog(title,description,onConfirm,label='Confirmar'){showDialog(esc(title),esc(description),`<div class="form-actions"><button class="btn ghost" data-action="close">Cancelar</button><button id="confirm-action" class="btn primary">${esc(label)}</button></div>`);document.querySelector('#confirm-action').onclick=()=>{modal.close();onConfirm();};}
function exportBackup(){const a=document.createElement('a'),u=URL.createObjectURL(new Blob([JSON.stringify(state,null,2)],{type:'application/json'}));a.href=u;a.download=`aeroping-backup-${new Date().toISOString().slice(0,10)}.json`;a.click();setTimeout(()=>URL.revokeObjectURL(u),1000);toast('Backup exportado. Guarde-o em um lugar seguro.');}
async function pushCloud(){if(cloudBusy||revision===null||!cloudDirty||cloudConflict||!signedIn())return;cloudBusy=true;const snapshot=JSON.stringify(state);let success=false;try{revision=await writeCloud(JSON.parse(snapshot),revision);cloudDirty=JSON.stringify(state)!==snapshot;success=true;}catch(e){cloudConflict=!!e.conflict;toast(e.message);}finally{cloudBusy=false;updateShell();if(view==='ajustes'||!signedIn())render();if(success&&cloudDirty&&!cloudConflict)cloudTimer=setTimeout(pushCloud,500);}}
async function connectCloud(){if(cloudBusy||!signedIn())return;cloudBusy=true;try{const remote=await readCloud();const incoming=remote.payload?validateState(remote.payload):freshState();const apply=()=>{state=incoming;revision=remote.revision;cloudDirty=false;cloudConflict=false;clearTimeout(cloudTimer);localStorage.setItem(STORE,JSON.stringify(state));render();};if(cloudDirty||cloudConflict){confirmDialog('Carregar os planos do casal?','As alterações locais serão substituídas. Exporte um backup antes se quiser guardá-las.',apply,'Carregar versão do casal');}else apply();}catch(e){toast(e.message);main.innerHTML='<div class="empty"><h2>Vamos tentar conectar de novo?</h2><p>Não foi possível abrir o espaço do casal. Confira a conexão e tente novamente.</p><button class="btn primary" data-action="sync">Tentar novamente</button><button class="btn ghost" data-action="logout" style="margin-left:8px">Sair</button></div>';}finally{cloudBusy=false;}}
async function checkSharedUpdates(){if(!signedIn()||document.hidden||cloudBusy||modal.open||cloudDirty||cloudConflict)return;try{if(revision===null){await connectCloud();return;}const remote=await cloudRevision();if(remote!==revision){if(cloudDirty||cloudBusy||modal.open)return;await connectCloud();}}catch{updateShell();if(!signedIn())render();}}
setInterval(checkSharedUpdates,30000);window.addEventListener('online',()=>{if(cloudDirty)pushCloud();else checkSharedUpdates();});window.addEventListener('focus',checkSharedUpdates);
document.addEventListener('click',async e=>{const b=e.target.closest('[data-action]');if(!b)return;const action=b.dataset.action,id=b.dataset.id,p=pingById(id);if(!signedIn()&&!['close','install'].includes(action)){toast('Entre para acessar os planos do casal.');return;}switch(action){
case 'close':modal.close();break;
case 'new':showPingForm();break;
case 'edit':showPingForm(id);break;
case 'detail':detail(id);break;
case 'quote':quoteForm(id);break;
case 'filter':filter=b.dataset.filter;render();break;
case 'profile':modal.close();location.hash='ajustes';break;
case 'alerts':location.hash='alertas';break;
case 'pause':if(p){p.paused=!p.paused;save();render();detail(id);toast(p.paused?'Radar pausado.':'Radar retomado.');}break;
case 'delete':if(p)confirmDialog('Excluir este radar?',`O destino ${p.city} e o seu histórico serão removidos.`,()=>{state.pings=state.pings.filter(x=>x.id!==id);save();render();toast('Radar excluído.');},'Excluir radar');break;
case 'clear-demo':confirmDialog('Começar com os nossos planos?','Os radares e alertas de demonstração serão removidos. Seus registros próprios serão preservados.',()=>{state.pings=state.pings.filter(x=>!x.demo);state.events=state.events.filter(x=>!x.demo);save();render();toast('Pronto para os seus destinos.');},'Remover exemplos');break;
case 'search':if(p){const query=`Voos ${p.origin} ${p.destination} ida ${p.depart} volta ${p.return} 2 adultos`;window.open(`https://www.google.com/travel/flights?q=${encodeURIComponent(query)}`,'_blank','noopener,noreferrer');}break;
case 'vote':if(p){const who=b.dataset.who;if(!['a','b'].includes(who))break;p.votes??={a:null,b:null};p.votes[who]=p.votes[who]==='yes'?null:'yes';const name=who==='a'?state.settings.nameA:state.settings.nameB;event('vote',`${name} ${p.votes[who]==='yes'?'topou':'está pensando em'} ${p.city}`,p.votes.a==='yes'&&p.votes.b==='yes'?'Os dois toparam! Confiram a tarifa antes de reservar.':'A decisão pode ser alterada a qualquer momento.',p.demo);save();render();}break;
case 'read-alerts':state.events.forEach(e=>e.read=true);save();render();toast('Pings marcados como lidos.');break;
case 'export':exportBackup();break;
case 'import':document.querySelector('#import-file').click();break;
case 'reset':confirmDialog('Apagar os planos deste espaço?','Isso remove todos os radares, históricos e decisões. Se estiver conectado, a remoção também será sincronizada com o casal. Exporte um backup antes.',()=>{state=freshState();save();render();toast('Espaço limpo.');},'Apagar planos');break;
case 'notifications':if(!('Notification'in window))toast('Este navegador não oferece notificações. No iPhone, instale o app pela tela inicial.');else{const permission=await Notification.requestPermission();state.settings.notifications=permission==='granted';save();toast(permission==='granted'?'Notificações ativadas com o app aberto.':'Notificações não autorizadas. Os pings continuam na central.');render();}break;
case 'install':if(installPrompt){await installPrompt.prompt();installPrompt=null;}else showDialog('Leve o AeroPing com você','Use o navegador para instalar na tela inicial.',`<div class="hint">iPhone / iPad: abra no Safari, toque em Compartilhar → Adicionar à Tela de Início.<br><br>Android / computador: abra o menu do Chrome ou Edge → Instalar aplicativo ou Adicionar à tela inicial.<br><br>A instalação depende do navegador. Para compartilhar os dados, configure a mesma conexão Supabase nos dois aparelhos.</div>`);break;
case 'sync':if(cloudConflict||revision===null)await connectCloud();else if(cloudDirty)await pushCloud();else await connectCloud();break;
case 'logout':confirmDialog('Sair deste aparelho?','A cópia local será limpa. Alterações ainda não sincronizadas serão perdidas; exporte um backup antes.',async()=>{clearTimeout(cloudTimer);await signOut();revision=null;cloudDirty=false;cloudConflict=false;state=freshState();localStorage.setItem(STORE,JSON.stringify(state));render();toast('Sessão encerrada. Dados locais removidos.');},'Sair e limpar');break;
}});
document.addEventListener('submit',async e=>{const form=e.target;if(!form.id)return;e.preventDefault();const data=new FormData(form),value=k=>String(data.get(k)||'').trim();const button=form.querySelector('[type=submit]');try{
if(form.id==='ping-form'){const old=pingById(form.dataset.id);if(!old&&state.pings.length>=100)throw Error('O espaço comporta até 100 radares.');const p={...(old||{}),id:old?.id||uid(),city:value('city'),country:value('country'),origin:value('origin').toUpperCase(),destination:value('destination').toUpperCase(),depart:value('depart'),return:value('return'),target:Number(value('target')),tolerance:Number(value('tolerance')),stops:value('stops'),baggage:data.has('baggage'),paused:old?.paused||false,photo:old?.photo||({LIS:'lisbon',CDG:'paris',HND:'tokyo',NRT:'tokyo'}[value('destination').toUpperCase()]||'other'),quotes:old?.quotes||[],votes:old?.votes||{a:null,b:null},createdAt:old?.createdAt||new Date().toISOString()};validatePing(p);if(old&&!old.demo&&old.quotes.length&&(old.origin!==p.origin||old.destination!==p.destination||old.depart!==p.depart||old.return!==p.return||old.stops!==p.stops||old.baggage!==p.baggage))throw Error('Para mudar trecho, datas, conexões ou bagagem com cotações existentes, crie outro radar. Isso mantém o histórico comparável.');if(old)state.pings[state.pings.findIndex(x=>x.id===old.id)]=p;else state.pings.unshift(p);save();modal.close();render();toast(old?'Radar atualizado.':'Nosso novo destino está no radar.');}
if(form.id==='quote-form'){const p=pingById(form.dataset.id);if(!p||p.demo)throw Error('Crie um radar próprio para registrar cotações.');const price=Number(value('price')),url=value('url');if(!Number.isFinite(price)||price<=0||price>1e7)throw Error('Informe um preço válido.');if(url&&!safeLink(url))throw Error('Use um link HTTPS válido.');const previous=latest(p);p.quotes.push({price,source:value('source'),url,at:new Date().toISOString()});p.quotes=p.quotes.slice(-1000);const alert=alertFor(p,previous);if(alert){event(alert.type,alert.title,alert.body);if(state.settings.notifications&&'Notification'in window&&Notification.permission==='granted'){try{new Notification(alert.title,{body:alert.body,icon:'./icon.svg'});}catch{}}}save();render();detail(p.id);toast(alert?alert.title:'Cotação registrada no histórico.');}
if(form.id==='profile-form'){state.settings.nameA=value('nameA')||'Eu';state.settings.nameB=value('nameB')||'Meu amor';save();render();toast('Nosso cantinho atualizado.');}
if(form.id==='miles-form'){const cash=Number(value('cash')),miles=Number(value('miles')),r=milesComparison(cash,miles,Number(value('thousand')),Number(value('taxes')));document.querySelector('#miles-result').innerHTML=`<div class="result-box"><h3>${Math.abs(r.saving)<.01?'As opções empatam':r.saving>0?'As milhas levam vantagem.':'O dinheiro leva vantagem.'}</h3><p>${Math.abs(r.saving)<.01?'O custo calculado é igual nas duas opções.':`Diferença estimada de <strong>${money(Math.abs(r.saving))}</strong> por pessoa e <strong>${money(Math.abs(r.saving)*2)}</strong> para o casal.`}</p><div class="result-numbers"><span>Em dinheiro<br><strong>${money(cash)}</strong></span><span>Com milhas + taxas<br><strong>${money(r.cost)}</strong></span></div><p style="margin-top:14px;font-size:10px">${r.breakEven>0?'Milhas compensam abaixo de '+money(r.breakEven)+' por milheiro, mantidas as mesmas condições.':'As taxas já são iguais ou superiores à passagem em dinheiro.'}</p></div>`;}
if(form.id==='cloud-config-form'){if(cloudBusy)throw Error('Aguarde a sincronização terminar.');configureCloud(value('url'),value('key'));revision=null;cloudDirty=false;cloudConflict=false;clearTimeout(cloudTimer);render();toast('Conexão salva. Entre na sua conta abaixo.');}
if(form.id==='login-form'){button.disabled=true;await signIn(value('email'),value('password'));form.reset();render();await connectCloud();}
}catch(error){const target=modal.open?document.querySelector('#modal-error'):null;if(target)target.textContent=error.message;else toast(error.message);}finally{if(button?.isConnected)button.disabled=false;}});
document.addEventListener('change',async e=>{if(e.target.id!=='import-file')return;const file=e.target.files?.[0];if(!file)return;try{if(file.size>5e6)throw Error('O backup deve ter até 5 MB.');const incoming=validateState(JSON.parse(await file.text()));confirmDialog('Restaurar este backup?',`${incoming.pings.length} radar(es) substituirão os registros atuais. Se estiver conectado, serão sincronizados com o casal.`,()=>{state=incoming;save();render();toast('Backup restaurado.');},'Restaurar');}catch(err){toast(err.message);}finally{e.target.value='';}});
window.addEventListener('hashchange',()=>{render();window.scrollTo({top:0});});
window.addEventListener('storage',e=>{if(e.key==='aeroping-session-v2'){try{if(JSON.parse(e.oldValue||'null')?.user?.id===JSON.parse(e.newValue||'null')?.user?.id)return;}catch{}revision=null;cloudDirty=false;cloudConflict=false;state=freshState();render();if(signedIn())connectCloud();return;}if(e.key!==STORE||!e.newValue||!signedIn()||cloudDirty)return;try{state=validateState(JSON.parse(e.newValue));render();}catch{toast('Outra aba atualizou os dados. Confira o backup antes de continuar.');}});
window.addEventListener('beforeinstallprompt',e=>{e.preventDefault();installPrompt=e;});
window.addEventListener('beforeunload',e=>{if(cloudDirty){e.preventDefault();e.returnValue='';}});
if('serviceWorker'in navigator)navigator.serviceWorker.register('./sw.js').catch(()=>{});
modal.addEventListener('click',e=>{if(e.target===modal){const r=modal.getBoundingClientRect();if(e.clientX<r.left||e.clientX>r.right||e.clientY<r.top||e.clientY>r.bottom)modal.close();}});
render();if(signedIn())connectCloud();

export const sharedUi={get state(){return state;},get status(){return {dirty:cloudDirty,conflict:cloudConflict,ready:revision!==null};},radarSvg,pageHeader,toast,configure(hooks){accessRenderer=hooks.access;settingsRenderer=hooks.settings;render();},async loginReady(){state=freshState();revision=null;cloudDirty=false;cloudConflict=false;render();await connectCloud();}};
